files.content:
:root {
  --bg: #1b1b2f;
  --card: #f5f0e1;
  --ink: #2b2b3c;
  --accent: #e94f37;
  --accent-dark: #b83a28;
  --muted: #6b6b7b;
  --line: #d8d2c0;
}

* {
  box-sizing: border-box;
}

[hidden] {
  display: none !important;
}

html {
  font-size: 18px;
}

body {
  margin: 0;
  min-height: 100vh;
  padding: 1.5rem 1rem;
  display: flex;
  align-items: flex-start;
  justify-content: center;
  background-color: var(--bg);
  background-image:
    linear-gradient(45deg, rgba(255,255,255,0.04) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.04) 75%),
    linear-gradient(45deg, rgba(255,255,255,0.04) 25%, transparent 25%, transparent 75%, rgba(255,255,255,0.04) 75%);
  background-size: 24px 24px;
  background-position: 0 0, 12px 12px;
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
}

.page {
  width: 100%;
  max-width: 640px;
}

.card {
  background: var(--card);
  border: 4px solid var(--ink);
  box-shadow: 8px 8px 0 var(--ink);
  padding: 1.5rem;
}

.card-header {
  border-bottom: 3px dashed var(--line);
  padding-bottom: 1rem;
  margin-bottom: 1rem;
}

h1 {
  margin: 0 0 0.25rem;
  font-size: 1.75rem;
  letter-spacing: 0.02em;
}

.subtitle {
  margin: 0 0 1rem;
  color: var(--muted);
  font-size: 1rem;
}

.controls {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.btn {
  font: inherit;
  font-weight: 700;
  color: var(--card);
  background: var(--accent);
  border: 3px solid var(--ink);
  padding: 0.5rem 1rem;
  cursor: pointer;
  box-shadow: 5px 5px 0 var(--ink);
  transition: transform 80ms ease, box-shadow 80ms ease, background-color 120ms ease;
}

.btn:hover {
  background: var(--accent-dark);
}

.btn:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 3px;
}

.btn:active {
  transform: translate(3px, 3px);
  box-shadow: 2px 2px 0 var(--ink);
}

.faq {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.faq-item {
  border: 3px solid var(--ink);
  background: #fffdf5;
}

.faq-heading {
  margin: 0;
  font-size: 1rem;
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  font: inherit;
  font-weight: 700;
  text-align: left;
  color: var(--ink);
  background: transparent;
  border: 0;
  padding: 0.85rem 1rem;
  cursor: pointer;
  transition: background-color 120ms ease;
}

.faq-question:hover {
  background: #f0e9d6;
}

.faq-question:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: -3px;
}

.faq-question:active {
  background: #e6ddc6;
}

.arrow {
  flex: 0 0 auto;
  width: 0;
  height: 0;
  border-left: 8px solid transparent;
  border-right: 8px solid transparent;
  border-top: 10px solid var(--accent);
  transition: transform 150ms ease;
}

.faq-question[aria-expanded="true"] .arrow {
  transform: rotate(180deg);
}

.faq-answer {
  padding: 0 1rem 1rem;
  border-top: 2px dashed var(--line);
  margin-top: 0;
  padding-top: 0.85rem;
}

.faq-answer p {
  margin: 0;
}

@media (max-width: 420px) {
  html {
    font-size: 17px;
  }

  body {
    padding: 1rem 0.75rem;
  }

  .card {
    padding: 1.1rem;
    box-shadow: 5px 5px 0 var(--ink);
  }

  h1 {
    font-size: 1.5rem;
  }
}

(function () {
  "use strict";

  var questions = Array.prototype.slice.call(
    document.querySelectorAll(".faq-question")
  );

  function getAnswer(button) {
    return document.getElementById(button.getAttribute("aria-controls"));
  }

  function setOpen(button, open) {
    var answer = getAnswer(button);
    button.setAttribute("aria-expanded", open ? "true" : "false");
    if (answer) {
      answer.hidden = !open;
    }
  }

  function collapseOthers(except) {
    questions.forEach(function (button) {
      if (button !== except) {
        setOpen(button, false);
      }
    });
  }

  questions.forEach(function (button) {
    button.addEventListener("click", function () {
      var isOpen = button.getAttribute("aria-expanded") === "true";
      if (isOpen) {
        setOpen(button, false);
      } else {
        collapseOthers(button);
        setOpen(button, true);
      }
    });
  });

  var expandAll = document.getElementById("expand-all");
  var collapseAll = document.getElementById("collapse-all");

  if (expandAll) {
    expandAll.addEventListener("click", function () {
      questions.forEach(function (button) {
        setOpen(button, true);
      });
    });
  }

  if (collapseAll) {
    collapseAll.addEventListener("click", function () {
      questions.forEach(function (button) {
        setOpen(button, false);
      });
    });
  }
})();
